typedef struct mem_reader {
    const giff_u8* src;
    giff_u32 size;
    giff_u32 pos;
    giff_u32 chunk;
} mem_reader;

static unsigned char k_workspace[1 << 20];

static int mem_read(void* user, giff_u8* dst, giff_u32* io_size)
{
    mem_reader* r;
    giff_u32 take;

    r = (mem_reader*)user;
    if (r == 0 || dst == 0 || io_size == 0) {
        return 0;
    }

    if (r->pos >= r->size) {
        *io_size = 0u;
        return 1;
    }

    take = *io_size;
    if (take > r->chunk) {
        take = r->chunk;
    }
    if (take > r->size - r->pos) {
        take = r->size - r->pos;
    }

    memcpy(dst, r->src + r->pos, (size_t)take);
    r->pos += take;
    *io_size = take;
    return 1;
}

static void init_cfg(giff_decoder_config* cfg)
{
    cfg->max_width = 32u;
    cfg->max_height = 32u;
    cfg->strict_mode = 1u;
    cfg->output_mode = (giff_u8)GIFF_OUTPUT_RGBA8888;
    cfg->restore_previous_mode = (giff_u8)GIFF_RESTORE_PREVIOUS_BOUNDS;
    cfg->capture_comments = 1u;
    cfg->user_canvas_stride = 0u;
    cfg->user_canvas_rgba = 0;
    cfg->user_previous_stride = 0u;
    cfg->user_previous_rgba = 0;
}

static void drive_event_loop(giff_decoder* dec, giff_result* out_rc)
{
    giff_result rc;
    giff_event ev;

    rc = GIFF_OK;
    while (1) {
        rc = giff_decoder_next_event(dec, &ev);
        if (rc != GIFF_OK) {
            break;
        }
        if (ev.type == GIFF_EVENT_TRAILER) {
            break;
        }
    }
    *out_rc = rc;
}

static void fuzz_seed(const giff_u8* seed, giff_u16 seed_size)
{
    giff_decoder dec;
    giff_decoder_config cfg;
    giff_result rc;
    giff_u8 mutated[128];
    giff_u16 iter;
    giff_u16 j;

    init_cfg(&cfg);

    for (iter = 0u; iter < 192u; ++iter) {
        giff_u16 mut_size;
        giff_u16 pos0;
        giff_u16 pos1;
        giff_u16 chunk;
        mem_reader reader;
        giff_io io;

        assert(seed_size < (giff_u16)sizeof(mutated));
        memcpy(mutated, seed, (size_t)seed_size);
        mut_size = seed_size;

        pos0 = (giff_u16)(iter % seed_size);
        pos1 = (giff_u16)((iter * 7u + 3u) % seed_size);
        mutated[pos0] ^= (giff_u8)(1u << (iter & 7u));
        mutated[pos1] ^= (giff_u8)(iter * 13u + 1u);

        if ((iter & 3u) == 0u && mut_size > 8u) {
            mut_size = (giff_u16)(mut_size - (iter % 5u) - 1u);
        } else if ((iter & 7u) == 3u && mut_size + 2u < (giff_u16)sizeof(mutated)) {
            mutated[mut_size++] = 0x00u;
            mutated[mut_size++] = 0x3Bu;
        }

        rc = giff_decoder_init(&dec, &cfg, k_workspace, (giff_u32)sizeof(k_workspace));
        assert(rc == GIFF_OK);
        rc = giff_decoder_decode_memory(&dec, mutated, (giff_u32)mut_size);
        assert(rc != GIFF_E_INTERNAL);

        rc = giff_decoder_init(&dec, &cfg, k_workspace, (giff_u32)sizeof(k_workspace));
        assert(rc == GIFF_OK);
        chunk = (giff_u16)((iter % 7u) + 1u);
        for (j = 0u; j < mut_size; j = (giff_u16)(j + chunk)) {
            giff_u32 take;
            take = chunk;
            if ((giff_u16)(j + chunk) > mut_size) {
                take = (giff_u32)(mut_size - j);
            }
            rc = giff_decoder_feed(&dec, mutated + j, take, 0);
            assert(rc != GIFF_E_INTERNAL);
            if (rc == GIFF_E_OUTPUT_OVERFLOW) {
                break;
            }
            drive_event_loop(&dec, &rc);
            assert(rc != GIFF_E_INTERNAL);
        }
        giff_decoder_finish_input(&dec);
        drive_event_loop(&dec, &rc);
        assert(rc != GIFF_E_INTERNAL);

        rc = giff_decoder_init(&dec, &cfg, k_workspace, (giff_u32)sizeof(k_workspace));
        assert(rc == GIFF_OK);
        reader.src = mutated;
        reader.size = (giff_u32)mut_size;
        reader.pos = 0u;
        reader.chunk = (giff_u32)((iter % 5u) + 1u);
        io.user = &reader;
        io.read = mem_read;
        io.write = 0;
        io.seek = 0;
        giff_decoder_attach_io(&dec, &io);
        rc = giff_decoder_begin_io(&dec);
        if (rc == GIFF_OK) {
            drive_event_loop(&dec, &rc);
            assert(rc != GIFF_E_INTERNAL);
        } else {
            assert(rc != GIFF_E_INTERNAL);
        }
    }
}

int main(void)
{
    fuzz_seed(k_seed_comment, (giff_u16)sizeof(k_seed_comment));
    fuzz_seed(k_seed_bad_min_code, (giff_u16)sizeof(k_seed_bad_min_code));
    fuzz_seed(k_seed_loop, (giff_u16)sizeof(k_seed_loop));
    fuzz_seed(k_seed_loader, (giff_u16)sizeof(k_seed_loader));
    fuzz_seed(k_seed_double_gce, (giff_u16)sizeof(k_seed_double_gce));
    fuzz_seed(k_seed_zero_delay, (giff_u16)sizeof(k_seed_zero_delay));
    fuzz_seed(k_seed_empty_comment, (giff_u16)sizeof(k_seed_empty_comment));
    fuzz_seed(k_seed_app_comment_empty, (giff_u16)sizeof(k_seed_app_comment_empty));
    fuzz_seed(k_seed_gce_comment_scope, (giff_u16)sizeof(k_seed_gce_comment_scope));
    fuzz_seed(k_seed_double_app_loop, (giff_u16)sizeof(k_seed_double_app_loop));
    return 0;
}
